def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re
    import sys

    sys.setrecursionlimit(max(sys.getrecursionlimit(), 100000))

    token_pattern = re.compile(
        r"\s*(<=|>=|<>|[A-Z][1-9][0-9]?|SUM|MIN|MAX|IF|[0-9]+|[()+\-*/,=:<>])"
    )

    def parse(content):
        if not content.startswith("="):
            return ("number", int(content))

        tokens = []
        position = 1
        while position < len(content):
            if content[position:].strip() == "":
                break
            match = token_pattern.match(content, position)
            tokens.append(match.group(1))
            position = match.end()

        index = 0

        def expression():
            nonlocal index
            node = term()
            while index < len(tokens) and tokens[index] in ("+", "-"):
                op = tokens[index]
                index += 1
                node = ("binary", op, node, term())
            return node

        def term():
            nonlocal index
            node = unary()
            while index < len(tokens) and tokens[index] in ("*", "/"):
                op = tokens[index]
                index += 1
                node = ("binary", op, node, unary())
            return node

        def unary():
            nonlocal index
            count = 0
            while tokens[index] == "-":
                count += 1
                index += 1
            node = atom()
            if count % 2:
                node = ("negate", node)
            return node

        def atom():
            nonlocal index
            token = tokens[index]
            index += 1

            if token.isdigit():
                return ("number", int(token))
            if token == "(":
                node = expression()
                index += 1
                return node
            if token in ("SUM", "MIN", "MAX"):
                index += 1  # opening parenthesis
                args = []
                while True:
                    if (
                        index + 1 < len(tokens)
                        and len(tokens[index]) >= 2
                        and tokens[index][0].isalpha()
                        and tokens[index][1:].isdigit()
                        and tokens[index + 1] == ":"
                    ):
                        start = tokens[index]
                        end = tokens[index + 2]
                        index += 3
                        args.append(("range", start, end))
                    else:
                        args.append(expression())
                    if tokens[index] != ",":
                        break
                    index += 1
                index += 1  # closing parenthesis
                return ("function", token, args)
            if token == "IF":
                index += 1  # opening parenthesis
                left = expression()
                op = tokens[index]
                index += 1
                right = expression()
                index += 1  # comma
                then = expression()
                index += 1  # comma
                otherwise = expression()
                index += 1  # closing parenthesis
                return ("if", op, left, right, then, otherwise)
            return ("reference", token)

        return expression()

    trees = {name: parse(content) for name, content in cells.items()}
    values = {}
    active = set()

    def evaluate_cell(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in active:
            return "#CYCLE!"
        active.add(name)
        value = evaluate(trees[name])
        active.remove(name)
        values[name] = value
        return value

    def evaluate(node):
        kind = node[0]

        if kind == "number":
            return node[1]
        if kind == "reference":
            return evaluate_cell(node[1])
        if kind == "negate":
            value = evaluate(node[1])
            return value if isinstance(value, str) else -value
        if kind == "binary":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient

        if kind == "if":
            left = evaluate(node[2])
            if isinstance(left, str):
                return left
            right = evaluate(node[3])
            if isinstance(right, str):
                return right
            op = node[1]
            if op == "=":
                condition = left == right
            elif op == "<>":
                condition = left != right
            elif op == "<":
                condition = left < right
            elif op == "<=":
                condition = left <= right
            elif op == ">":
                condition = left > right
            else:
                condition = left >= right
            return evaluate(node[4] if condition else node[5])

        function = node[1]
        result = None
        for arg in node[2]:
            if arg[0] == "range":
                start, end = arg[1], arg[2]
                first_col = min(ord(start[0]), ord(end[0]))
                last_col = max(ord(start[0]), ord(end[0]))
                first_row = min(int(start[1:]), int(end[1:]))
                last_row = max(int(start[1:]), int(end[1:]))
                names = (
                    chr(col) + str(row)
                    for row in range(first_row, last_row + 1)
                    for col in range(first_col, last_col + 1)
                    if chr(col) + str(row) in cells
                )
                for name in names:
                    value = evaluate_cell(name)
                    if isinstance(value, str):
                        return value
                    if result is None:
                        result = value
                    elif function == "SUM":
                        result += value
                    elif function == "MIN":
                        result = min(result, value)
                    else:
                        result = max(result, value)
            else:
                value = evaluate(arg)
                if isinstance(value, str):
                    return value
                if result is None:
                    result = value
                elif function == "SUM":
                    result += value
                elif function == "MIN":
                    result = min(result, value)
                else:
                    result = max(result, value)
        return 0 if result is None else result

    return {name: evaluate_cell(name) for name in cells}
